INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(800, 0, 8, 0, 0, 0, 'Swamp of Sorrows', 'The Swamp of Sorrows was once the northern reach of the Black Morass, a vast marshland whose southern half became barren waste after the Dark Portal was destroyed, the land now called the Blasted Lands. What remained was named in honor of those who died in the Second War. Long before, the Atal''ai, exiled priests of the Gurubashi trolls, raised a temple here to their blood god Hakkar, until Ysera of the green dragonflight drowned it beneath the Pool of Tears. Green dragons and their kin still guard the ruin. The orcs of Stonard hold the south as a Horde foothold, while Alliance caravans struggle along the road to Nethergarde Keep. In the north, Broken exiles shelter at the Harborage, beset by the Lost Ones, their own kin driven mad by the journey from Draenor. Murlocs crowd the misty eastern shore, jaguars and crocolisks stalk the mire, and beside the southern road the ghost of an orc hero still waits for orders that never came.', 'warcraft.wiki.gg/wiki/Swamp_of_Sorrows (Black Morass, southern part became barren after the Dark Portal was destroyed, named in honor of Second War dead, Atal''ai temple, Ysera drowned it, Stonard); warcraft.wiki.gg/wiki/Temple_of_Atal''Hakkar (exiled Gurubashi priests fled north into the swamp); quest 1389 description (Lost Ones driven mad by the rigors of the journey to Azeroth); quests 1396, 1421, 1425 (Alliance caravans to Nethergarde); npc_text 1392, quest 2621 (Fallen Hero awaiting orders); DB spawns: Marsh murlocs on the coast, Swamp Jaguar and Sawtooth Crocolisk in the mire'),
(801, 1, 8, 1, 0, 0, 'Misty Valley', 'Misty Valley lies in the northwest corner of the swamp, just north of where the road climbs away toward Deadwind Pass. Fog clings to its sodden floor, and the valley belongs to the swamp itself. Swampwalkers and tangled horrors, lumbering plant-like creatures of root and muck, wander between its pools, and a hulking elemental called the Mire Lord dwells in the valley''s cave. Such creatures are no friend to travelers. A courier carrying an essay of Khadgar''s to Nethergarde Keep once took a wrong turn in the swamp and fled from them in terror, and one of the beasts made off with the precious pages.', 'warcraft.wiki.gg/wiki/Misty_Valley (northwest corner, north of the entrance to Deadwind Pass; pre-Cataclysm Tangled Horrors, Swampwalkers, Swampwalker Elders; Mire Lord in the valley''s cave); quest 1364 description (courier, wrong turn, plant-like swamp creatures, essay taken); creature_loot_template: item 6065 Khadgar''s Essays drops from 764, 765, 766, 1081; DB: Mire Lord 1081 (type elemental) at area 116; Swampwalker and Tangled Horror spawns in area 116'),
(802, 1, 8, 2, 0, 0, 'Splinterspear Junction', 'Splinterspear Junction is where the main road into the swamp divides. The northern branch runs past the Harborage toward the Fallow Sanctuary, while the southern branch bends toward Stonard and the long road to the Blasted Lands. An old orcish watchtower stands near the fork, and scouts out of Stonard keep an eye on the crossing, for beyond it lies Horde country. Alliance travelers on the way to Nethergarde learn to watch the roads here. A short way to the south, the stranded Watcher Biggs keeps lonely guard over the remains of his caravan.', 'warcraft.wiki.gg/wiki/Splinterspear_Junction (main road splits; north branch past the Harborage to Fallow Sanctuary, south branch to Stonard and the Blasted Lands; old orcish watch tower; Horde patrols); DB spawns: Stonard Scout 861 (faction 29) around -10390,-2640 in area 1780; quest 9609 (Watcher Biggs is to the south); DB spawn Watcher Biggs 5476 at -10535,-2836'),
(803, 1, 8, 3, 0, 0, 'The Harborage', 'In the north of the swamp, a cluster of leather huts hung with crystals makes up the Harborage, refuge of the Broken who kept their minds after crossing from Draenor. Their leader Magtoor knows how few they are. The Lost Ones of the Fallow Sanctuary, once their own brethren, kill any who wander near, and they have stolen the sacred draenethyst the exiles fear they cannot do without. The village keeps on careful terms with nearby Stonard, a choice that troubles the draenei Anchorite Avuun, who has come to study the Lost Ones in hope of a cure. The Broken scholar Holaaru studies Atal''ai relics, hoping to understand the history of his new world.', 'warcraft.wiki.gg/wiki/The_Harborage (pre-Cataclysm: base of Broken who stayed sane, leather huts hung with crystals); quest 1389 description; creature_text 1776 (Magtoor on honoring the Horde), creature_text 17127 (Avuun: why do you traffic with the Horde); npc_text 8812, 9270; quest 9610 reward text (Holaaru); DB spawns: Magtoor 1776, Anchorite Avuun 17127, Holaaru 18221, Broken Exile 11198 in area 657'),
(804, 1, 8, 4, 0, 0, 'Itharius''s Cave', 'In the hills along the swamp''s western edge lies the lair of Itharius, who receives visitors in the guise of an elf but speaks for Ysera''s green dragonflight. He shares the cave with a brood of green whelps, adolescents and dreamers alike, that snap at anyone who intrudes. These whelps carry a fine dream dust valued well beyond the swamp: a goblin of Booty Bay who trades in secrets will name his price in it before he gives one away. Few who find the cave know why its master is here. He waits for someone who has walked the sunken temple and can help end his brother''s torment.', 'warcraft.wiki.gg/wiki/Itharius (cave near the edge of the swamp, looks after green whelps, appears as an elf in Classic); gossip_menu_option 1341 (What''s an elf like you doing inside a cave like this?); npc_text 1997 (brother trapped in a nightmare); quest 1116 description (dream dust from the dragon whelps of the Swamp of Sorrows, Krazek in Booty Bay); DB spawns: Itharius 5353, Adolescent Whelp 740, Dreaming Whelp 741 only in area 1777'),
(805, 1, 8, 5, 0, 0, 'Fallow Sanctuary', 'Fallow Sanctuary is the village of the Lost Ones in the north of the swamp, east of the Harborage and within sight of the Redridge Mountains. Its huts and campfires belong to draenei twisted further than the Broken, maddened by the journey from their homeworld and hostile to every outsider. Hunters, fishermen, cooks, seers and riftseekers keep up a grim semblance of village life under their chieftains, guarding the draenethyst they stole from the Harborage. One of them, Ongeku, holds a shard so prized that the Gelkis centaurs of distant Desolace covet it. Beasts are kept in cages here, a captive human sits in another, and loot from a plundered Alliance caravan lies scattered nearby.', 'warcraft.wiki.gg/wiki/Fallow_Sanctuary (village of the Lost Ones, within view of Redridge, driven mad with homesickness); quest 1389 description; quest 1373 description (Gelkis of Desolace, draenethyst shard held by Ongeku); quest 9440 description (caged animals at the Fallow Sanctuary); quest 1421 description (wagon dragged to the Fallow Sanctuary); DB spawns in area 76: Lost One Hunter, Fisherman, Cook, Seer, Riftseeker, Chieftain, Draenethyst Crystals, Captured Tarantula/Crocolisk; Galen''s Cage 37118 and Caravan Chest 28024 just outside the area line; creature_queststarter: Uthek the Wise 5397 starts 1373'),
(806, 1, 8, 6, 0, 0, 'The Shifting Mire', 'The Shifting Mire is the broad, sodden heart of the swamp, lying west of the Pool of Tears. Swamp jaguars hunt between its twisted trees alongside sorrow spinners and young sawtooth crocolisks, and a thorny elemental known as Molt Thorn wanders its paths. Lost Ones wade the shallows, fishing and scavenging far from their village. North of Stonard, a man named Galen Goodward once kept his camp in the mire, and his strongbox still waits there, its keyhole stopped with black resin so that no key will ever turn it.', 'warcraft.wiki.gg/wiki/The_Shifting_Mire (central section west of the Pool of Tears; jaguars, spinners, young crocolisks, Lost Ones); DB spawns in area 1798: Swamp Jaguar x22, Molt Thorn 14448 (type elemental), Sorrow Spinner, Young Sawtooth Crocolisk, Lost One Mudlurker and Fisherman; quest 1393 description and reward text; gameobject 32569 Galen''s Strongbox in area 1798'),
(807, 1, 8, 7, 0, 0, 'Stonard', 'Stonard is one of the oldest orc settlements in Azeroth, first raised by the old Horde as an outpost in the Black Morass after the Dark Portal opened. Probably lost in the wars that followed, it has been re-established by the new Horde, and it still keeps a great hall guarded by two burrows. Here Fel''zerul studies the sunken temple at the Warchief''s command, Helgrum the Swift struggles to keep word flowing to distant Kargath, and Dispatch Commander Ruag relays the orders of Orgrimmar. Wayfinders and cartographers set out to chart the unmapped swamp. A captured human spy waits in custody, and a blood elf warlock named Cersei Dusksinger is perfecting a curse meant for the draenei.', 'warcraft.wiki.gg/wiki/Stonard (founded by the Old Horde in the Black Morass after the first opening of the Dark Portal, re-established by the new Horde, great hall and two burrows, wayfinders and cartographers mapping the swamp); quest 1424 description; quest 1418 description; quest 2622 description; quest 1372 description (human infiltrator taken to Stonard); quest 9440 description; DB spawns: Stonard Wayfinder 865, Stonard Cartographer 867, Infiltrator Marksen 5416 in area 75; quest 1418 reward text (Neeka''s outrunner to Stonard)'),
(808, 1, 8, 8, 0, 0, 'Pool of Tears', 'The Pool of Tears is the great lake on the eastern side of the swamp, and beneath its dark water lies the Temple of Atal''Hakkar. The Atal''ai trolls built it to call their blood god Hakkar into the world, and the green dragonflight sank it to stop them. Ruins of the Atal''ai still lie scattered along the shore and under the water, where relics and tablets can be found, and cursed and mummified trolls haunt the stones. Ravenous sawfin frenzies swarm the water. Green dragonkin stand guard over the place, among them the ancient drake Somnus and the dragon Jade, who would sooner destroy an intruder than let one enter the temple.', 'warcraft.wiki.gg/wiki/Pool_of_Tears (pre-Cataclysm lake, temple sunk under its waters, Atal''ai ruins at the shore and underwater, frenzies); warcraft.wiki.gg/wiki/Temple_of_Atal''Hakkar; quest 9610 description (Somnus, dragonkin, carnivorous fish); creature_text 1063 (Jade); DB spawns in area 74: Atal''ai Artifact and Atal''ai Tablet objects, Cursed/Mummified/Enthralled Atal''ai, Sawfin Frenzy 14356, Somnus 12900, Jade 1063'),
(809, 1, 8, 9, 0, 0, 'Sorrowmurk', 'East of the Pool of Tears and the sunken temple lies Sorrowmurk, a stretch of swamp held by the green dragonflight. Scalebane captains, wyrmkin dreamwalkers and elder dragonkin patrol its pools in such numbers that few but the boldest travelers try to cross it, and among them walks a rare dragonspawn called Lord Captain Wyrmak. The dragons are not alone. Atal''ai priests and the cursed and mummified remnants of their tribe still creep through the murk, close to the drowned temple of their god.', 'warcraft.wiki.gg/wiki/Sorrowmurk (just east of the Pool of Tears and the Sunken Temple, crawling with green dragonspawn, inhospitable for all but the most adventurous); warcraft.wiki.gg/wiki/Lord_Captain_Wyrmak (rare green dragonspawn in Sorrowmurk); DB spawns in area 1778: Scalebane Captain 745, Elder Dragonkin 746, Wyrmkin Dreamwalker 743, Lord Captain Wyrmak 14445, Atal''ai Priest, Cursed and Mummified Atal''ai'),
(810, 1, 8, 10, 0, 0, 'Stagalbog', 'Stagalbog is the dense marsh south of the Pool of Tears, pressed up against the mountains along the swamp''s southern border. Deathstrike tarantulas lurk among the trees, and murlocs of the marsh tribes, inkspewers, flesheaters and oracles, range inland from the coast. A cave at the edge of the mountains shelters a murloc called the Swamp Talker, who can summon the spirits of the swamp to fight beside it. When murlocs ambushed a party of Stonard soldiers bound for the Blasted Lands, it was the Swamp Talker who tore the Warchief''s orders from a messenger''s hands as a spear struck him down.', 'warcraft.wiki.gg/wiki/Stagalbog (south of the Pool of Tears, borders the southern mountain range, Stagalbog Cave at the edge of the mountains); warcraft.wiki.gg/wiki/Swamp_Talker (located in Stagalbog Cave, Summon Swamp Spirit); quest 2622 and 2623 descriptions (ambush, Swamp Talker took the orders); creature_loot: item 8463 Warchief''s Orders from Swamp Talker 950; DB spawns in area 1797: Deathstrike Tarantula, Marsh Inkspewer, Flesheater, Oracle; Swamp Talker 950 at -10967,-3658'),
(811, 1, 8, 11, 0, 0, 'Misty Reed Strand', 'Misty Reed Strand is the long, fog-bound coast along the swamp''s eastern edge, where the marsh gives way to the Forbidding Sea. Marsh murlocs crowd the shore in great numbers, and monstrous crawlers and sawtooth snappers scuttle through the surf. Sun-dried driftwood washes up among the reeds, prized by anyone in the swamp who needs timber sounder than the spongy wood of its trees. Stonard keeps a close eye on this coast. The orc Katar patrols the beach, nursing a bitter hatred of the sea and of every fish man it spawns, and crawler legs gathered here are shipped all the way to Orgrimmar.', 'warcraft.wiki.gg/wiki/Misty_Reed_Strand (gloomy coastline, driftwood, crocolisks, crabs, murlocs; Alliance collect driftwood, Horde hunt murlocs); quest 1398 description (strong, dry wood, not the spongy wood of the swamp''s trees); quest 1426 description (Katar); quest 1430 description (crawler legs shipped to Orgrimmar); DB spawns in area 300: Marsh Inkspewer x38, Silt Crawler, Monstrous Crawler, Sawtooth Snapper, Sundried Driftwood objects, Katar 5593'),
(812, 1, 8, 12, 0, 0, 'Misty Reed Post', 'Just inland from the southern end of Misty Reed Strand, a small Horde camp keeps watch over the sea. Tok''Kar and his soldiers are stationed here to hold back the murlocs, or to warn Stonard if a force comes too large to stop. Between shifts of guard duty Tok''Kar cooks for his troops and forges weapons from the claws of sawtooth snappers, for the more blades the camp has ready, the better its chances. It is a spare life of fire, mead and steel, and Tok''Kar admits he would not mind if Stonard one day sent them a proper burrow, or at least a tower.', 'quest 698 description (outpost near the beach, guard duty and cooking); quest 699 description, reward and request texts (protect or warn Stonard, weapons from claws, burrow or tower); DB spawns in area 1978: Tok''Kar 5592, Stonard Hunter 863 x5, Stonard Shaman 868'),
(813, 2, 8, 1, 0, 0, 'Itharius', 'Itharius greets visitors to his cave in the guise of an elf, but he is a green dragon of Ysera''s flight. He knows the history of the god the Atal''ai called forth: the dragons destroyed its physical form and sank its temple, yet its corruption ran deeper than they believed. His brother Eranikus, charged with watching over the sunken temple, fell to it unwittingly and now lies trapped in a nightmare within the Dream itself. Eranikus'' agony roused Itharius from his own dreaming, and he has made it his charge to end that torment. He speaks much of choices, and insists that there are correct ones.', 'warcraft.wiki.gg/wiki/Itharius (green dragon, appears as a high elf in Classic, Ysera''s flight); npc_text 1995, 1997, 1998, 1999; creature 5353 faction 35 (friendly to all)'),
(814, 2, 8, 2, 0, 0, 'Magtoor', 'Magtoor leads the Broken exiles of the Harborage, among the few draenei who came through the Dark Portal and kept their reason. He has watched his former brethren at the Fallow Sanctuary become monsters that prey on his people, and he fears that without their sacred draenethyst the exiles too may lose their way. Magtoor is a realist about his neighbors. He trades with merchants in Stonard and believes the Horde would crush his village if it failed to honor them. He welcomes Anchorite Avuun to the Harborage, yet asks him plainly what he truly believes he can accomplish.', 'warcraft.wiki.gg/wiki/Magtoor (pre-Cataclysm: Broken leader of a small group who kept their noble roots, came through the Dark Portal); quest 1389 description; creature_text 1776 groups 0-3; creature 1776 faction 35'),
(815, 2, 8, 3, 1, 0, 'Anchorite Avuun', 'Anchorite Avuun is a draenei who has come to the Harborage to study the Lost Ones of the Fallow Sanctuary. He has faith that the fel energies consuming them can be cured, and that the same cure would undo the damage done to the Broken. He has little patience for the village''s dealings with the Horde, whose foul ways he thinks beneath his hosts. His gravest fear lies in Stonard. He is certain the blood elf Cersei Dusksinger is cursing the Lost Ones with still darker fel magic, and for those already twisted past saving, he asks only that they be granted mercy.', 'npc_text 8812; creature_text 17127 groups 0, 1, 3; quest 9448 description and reward text; warcraft.wiki.gg/wiki/The_Harborage (Avuun arrived to study the Broken and look for a cure, urged residents to stop trading with the Horde)'),
(816, 2, 8, 4, 2, 0, 'Cersei Dusksinger', 'Cersei Dusksinger is a blood elf warlock working out of Stonard, and she has little good to say about the swamp, its air or the food in Stonard. She is perfecting a weapon against the draenei, testing fel-tainted morsels on the captive livestock of the Lost Ones so that the curse passes into whoever eats them. She scorns the orcs for sitting idle while others plunder the power that lies so close at hand. Anchorite Avuun''s opposition she takes as a personal challenge, vowing that when she is finished, the draenei will wish they were Lost Ones.', 'quest 9440 description and reward text; creature_text 17109 (orcs are fools, Avuun dares to oppose me, cured ham steak from Thultash, no fresh air in this swamp); warcraft.wiki.gg/wiki/Cersei_Dusksinger (blood elf warlock in Stonard); creature 17109 faction 1604 (Silvermoon, enemy of Alliance)'),
(817, 2, 8, 5, 0, 0, 'Fallen Hero of the Horde', 'Beside the southern road toward the Blasted Lands stands the ghost of the orc who commanded Thrall''s Grasp, twenty of the Warchief''s most accomplished and honored soldiers. He had the regiment make camp here on the border to await orders from Orgrimmar, but weeks passed without word, and young and ambitious, he led them into the Blasted Lands. They were overwhelmed. He fled, then returned to rescue his men, only to be captured and tortured beside his lieutenant, Kirith, until he was beaten to death. Now his spirit lingers where he made his choice, warning travelers of what lies beyond and seeking anyone willing to set his soldiers free.', 'npc_text 1391, 1392, 1411, 1451, 1452; quest 2621 description; quest 2743 (Kirith calls him Trebor); warcraft.wiki.gg/wiki/Fallen_Hero_of_the_Horde (Trebor, ghost beside the road south toward the Blasted Lands); creature 7572 faction 35'),
(818, 2, 8, 6, 2, 0, 'Fel''zerul', 'Fel''zerul came to Stonard on the Warchief''s orders to look into strange happenings at the Temple of Atal''Hakkar, only to find the temple already sunk beneath the Pool of Tears and green dragons claiming to guard it. He has set out to piece the mystery together from Atal''ai relics, hoping their dark spells might prove useful to the Horde. A sentence of exile written in blood on dried flesh led him to a disgraced Atal''ai priest, and to the prophecy of Jammal''an. When the fetishes of Hakkar are finally laid before him, he destroys them as instruments of evil.', 'quest 1424 description and request text; quest 1429 description; quest 1444 description; quest 1445 description; creature_text 1443 (I hereby destroy these instruments of evil! For the Horde!); creature 1443 faction 29'),
(819, 2, 8, 7, 1, 0, 'Watcher Biggs', 'Watcher Biggs was escorting a caravan from Darkshire bound for Nethergarde Keep when Lost Ones fell upon it, killing the guards and scattering the supplies. He alone survived. Stunned in the attack, he glimpsed one of the wagons being dragged north to the Fallow Sanctuary, carrying reagents the wizards of Nethergarde need for their work at the Dark Portal. Since then he has camped beside his broken wagon south of the Harborage, sworn to protect what remains from the swamp''s beasts, and waiting for strong, dry wood to mend it so the shipment can finally go through.', 'quest 9609 description (caravan from Darkshire, sole survivor, south of the Harborage); quest 1396 description; quest 1421 description and reward text; quest 1398 description; creature 5476 faction 12 (Stormwind, enemy of Horde)'),
(820, 2, 8, 8, 0, 0, 'Galen Goodward', 'Galen Goodward is a human who made his camp in the swamp north of Stonard, and who now sits in a cage at the edge of the Fallow Sanctuary, certain his captors mean to eat him. He promises great treasure to anyone who will lead him to safety: a strongbox in his camp, its keyhole filled with black resin so that it cannot be picked, which opens only by a hidden latch on its underside. Once free he whispers the trick, swears he will never forget his rescuer, and slips away into the swamp. Even Cersei Dusksinger in Stonard knows of the human in the cage.', 'quest 1393 description and reward text; creature_text 5391 groups 3-5; quest 9440 request text (that stupid human they have out there in the cage); gameobject 37118 Galen''s Cage at -9898,-3724; 32569 Galen''s Strongbox in area 1798; creature 5391 faction 35'),
(821, 2, 8, 9, 0, 0, 'Noboru the Cudgel', 'Noboru the Cudgel is a Lost One who roams the swamp with his gang, killing any draenei who cross his path. For months he has been a terror to the Harborage, and the Broken admit they never had the strength to face him. His great club has become a symbol of all the brutality they have suffered at the hands of their maddened kin. Whoever brings that cudgel back to the Harborage is welcomed as a true friend of the exiles, and the day of his death is counted a joyous one.', 'quest 1392 description and reward text; creature 5477 faction 51 (hostile to all), spawn at -10174,-3505'),
(822, 2, 8, 10, 0, 0, 'Somnus', 'Somnus is an ancient drake of the green dragonflight who dwells at the Pool of Tears with his dragonkin, above the drowned Temple of Atal''Hakkar. Anyone who goes digging for Atal''ai relics along the shore is warned of him first. His renown reaches even the black dragonflight. The black drake Emberstrife names him the drake champion of the Green Flight and sends Horde warriors into the swamp to bring back his skull, as proof that the children of the Aspects can be humbled as surely as the Aspects themselves.', 'quest 9610 description (guarded by Somnus, an ancient green dragon, and his dragonkin); quest 6583 description (Emberstrife: Somnus, drake champion of the Green Flight; bring his skull); DB spawn: Somnus 12900 at -10661,-3924 (area 74); warcraft.wiki.gg/wiki/Somnus'),
(823, 3, 8, 1, 0, 0, 'The Sunken Temple', 'Horde and Alliance alike have come looking for the Temple of Atal''Hakkar. In Stormwind, the aged dwarf Brohann Caskbelly asks for help with his final task for the Explorers'' League, a temple he once hunted by gryphon and never found. Searchers learn it lies sunk beneath the Pool of Tears and ringed by green dragons, and a tipsy gryphon rider who fell into the pool and swam out among the trolls sends back a troll relic to prove it. At the Harborage, the Broken scholar Holaaru seeks Atal''ai relics to learn the history of his new world. In Stonard, Fel''zerul gathers the same artifacts for the Horde, and a sentence written in blood leads him to an Atal''ai priest exiled to the Hinterlands. The exile tells of Jammal''an the Prophet, who believes Hakkar''s return will make his tribe immortal, and warns that if the right fetishes are enchanted for the summoning, the world lies in great peril.', 'quests 1448, 1469, 1475 (Brohann Caskbelly, Rhapsody Shindigger); quest 9610; quests 1424, 1429, 1444, 1445, 1446'),
(824, 3, 8, 2, 0, 0, 'The Lost Ones', 'The Broken of the Harborage and the Lost Ones of the Fallow Sanctuary were once one people. Magtoor asks for help taking back the draenethyst crystals his maddened kin have stolen, without which his exiles fear they will lose their way as well, and whoever brings down the brutal Noboru the Cudgel earns the whole village''s thanks. Anchorite Avuun studies the Lost Ones in the hope of a cure. But another hand is at work. In Stonard, Cersei Dusksinger has willing helpers feed fel-tainted morsels to the Lost Ones'' caged livestock, so the curse will pass to those who slaughter and eat them, a trial for a weapon she means to turn on the draenei. The Cursed Lost Ones she creates are beyond help, and Avuun asks only that they be given a merciful end.', 'quests 1389, 1392, 9440, 9448 (descriptions and reward texts); creature_text 17109, 17127'),
(825, 3, 8, 3, 0, 0, 'Thrall''s Grasp', 'The ghost on the road to the Blasted Lands tells his tale to anyone who will listen. Impatient for orders that never came, he led the regiment Thrall''s Grasp into the Blasted Lands, where it was destroyed. To the Horde he confesses he must know what became of those orders. Dispatch Commander Ruag in Stonard swears he sent them, but murlocs ambushed the messengers, and the lone survivor, Bengor, can barely speak of a creature called the Swamp Talker. The recovered orders confirm the hero''s fear that nineteen of his men need never have suffered. An Alliance ambassador at Nethergarde urges his own people to set aside old quarrels and hear the orc as well. The fate of the regiment is worse than death: the demon lord Razelikh tore out their souls, kept nine bound to stones near the Dark Portal and gave the rest to his lieutenants. Eighteen stones of binding must be shattered to free them.', 'npc_text 1392, 1451-1456; quests 2784, 2621, 2622, 2623, 2783, 2801, 2681 (descriptions and reward texts); warcraft.wiki.gg/wiki/Fallen_Hero_of_the_Horde'),
(826, 3, 8, 4, 1, 0, 'The Lost Caravan', 'Supplies for Nethergarde Keep travel from Darkshire by the swamp road, and not all of them arrive. When Lost Ones ambushed one such caravan, only Watcher Biggs survived, and even the draenei of the Harborage send word that he needs help. Biggs first asks that the jaguars, spiders and young crocolisks closing in on his camp be driven back. Then he remembers the wagon dragged off to the Fallow Sanctuary with a chest of reagents for Nethergarde''s wizards, whose work at the Dark Portal is vital to the Alliance. To mend his own wagon he needs sun-dried driftwood from the eastern coast, since the swamp''s own timber is too spongy to serve. At last he entrusts the most vital supplies to his rescuer for the final road to Nethergarde, where the quartermaster had already given Biggs and his caravan up for lost.', 'quests 9609, 1396, 1421, 1398, 1425 (descriptions and reward texts)'),
(827, 3, 8, 5, 2, 0, 'Threat from the Sea', 'Stonard''s eastern flank faces the sea, and the Horde takes the danger seriously. Dar, a trader in Stonard, gathers sawtooth meat for the soldiers at Misty Reed Post and monstrous crawler legs for his customers in Orgrimmar. At the post, Tok''Kar welcomes the fresh meat, turns sawtooth snapper claws into weapons for the camp''s defense, and sends willing hands on to Katar, who walks the beach on patrol. Katar''s hatred of the sea and the murlocs it spawns runs deep. He calls himself as patient and enduring as an old stone of Draenor, and would cleanse every world of the fish men if he had the army to do it. Each murloc slain along the strand brings him a grim pleasure, and Tok''Kar rewards those who bring a smile to Katar''s face with one of his finished blades.', 'quests 698, 699, 1422, 1426, 1427, 1428, 1430 (descriptions, request and reward texts)'),
(828, 3, 8, 6, 0, 0, 'The Dreamer''s Charge', 'Within the sunken temple lies a gem that holds part of the essence of Eranikus, the green dragon set to guard it. Through it Eranikus begs to be cleansed, but the essence font of his lair has itself been tainted by Hakkar, and he is dragged into an eternal nightmare. Those who carry the gem may find their way to Itharius in his cave in the swamp, who gives them an oathstone of Ysera''s Dragonflight. Engaging it, they swear to help redeem a soul worthy of redemption, and surrender the gem as the first of many sacrifices. Itharius then begins the slow work of reaching his brother, who lies caught between sleep and death. The first step leads far north to Winterspring, to seek out Umbranse the Spiritspeaker, a human medium who speaks for the dead.', 'quest 3373 description and reward text; quest 3374 description and reward text; quest 3512 description; creature_text 5353 (I have given you an oathstone); item 10589 Oathstone of Ysera''s Dragonflight starts 3374; item 10454 Essence of Eranikus starts 3373; quest_template_addon 3374 PrevQuestID 3373');
